render_chart <- function(data, cfg, manifest) { nums <- data[vapply(data, function(x) all(na.omit(x) %in% c(0, 1)), logical(1))]; if (ncol(nums) < 2) stop("UpSet 图至少需要两列 0/1 集合成员列"); keys <- apply(nums, 1, paste0, collapse = ""); counts <- sort(table(keys), decreasing = TRUE); d <- data.frame(intersection = names(counts), count = as.integer(counts)); p <- ggplot2::ggplot(d, ggplot2::aes(x = reorder(intersection, count), y = count)) + ggplot2::geom_col(fill = cfg$color %||% "#0A84FF") + ggplot2::coord_flip() + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% "集合交集规模", x = "交集组合（按列顺序）", y = "记录数"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
